WITH with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_session_tier, DATE_TRUNC('WEEK', started_at) AS week_start, SIZE(COLLECT_SET(country)) AS num_countries, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, ROUND(AVG(session_no), 2) AS avg_session_no, GROUPING_ID() AS grouping_level FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', started_at)), (CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END))
